export const OTLP_PROTO_LOGS = "// Copyright 2020, OpenTelemetry Authors\n//\n// Licensed under the Apache License, Version 2.0 (the \"License\");\n// you may not use this file except in compliance with the License.\n// You may obtain a copy of the License at\n//\n//     http://www.apache.org/licenses/LICENSE-2.0\n//\n// Unless required by applicable law or agreed to in writing, software\n// distributed under the License is distributed on an \"AS IS\" BASIS,\n// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n// See the License for the specific language governing permissions and\n// limitations under the License.\n\nsyntax = \"proto3\";\n\npackage opentelemetry.proto.logs.v1;\n\nimport \"opentelemetry/proto/common/v1/common.proto\";\nimport \"opentelemetry/proto/resource/v1/resource.proto\";\n\noption csharp_namespace = \"OpenTelemetry.Proto.Logs.V1\";\noption java_multiple_files = true;\noption java_package = \"io.opentelemetry.proto.logs.v1\";\noption java_outer_classname = \"LogsProto\";\noption go_package = \"go.opentelemetry.io/proto/otlp/logs/v1\";\n\n// LogsData represents the logs data that can be stored in a persistent storage,\n// OR can be embedded by other protocols that transfer OTLP logs data but do not\n// implement the OTLP protocol.\n//\n// The main difference between this message and collector protocol is that\n// in this message there will not be any \"control\" or \"metadata\" specific to\n// OTLP protocol.\n//\n// When new fields are added into this message, the OTLP request MUST be updated\n// as well.\nmessage LogsData {\n  // An array of ResourceLogs.\n  // For data coming from a single resource this array will typically contain\n  // one element. Intermediary nodes that receive data from multiple origins\n  // typically batch the data before forwarding further and in that case this\n  // array will contain multiple elements.\n  repeated ResourceLogs resource_logs = 1;\n}\n\n// A collection of ScopeLogs from a Resource.\nmessage ResourceLogs {\n  reserved 1000;\n\n  // The resource for the logs in this message.\n  // If this field is not set then resource info is unknown.\n  opentelemetry.proto.resource.v1.Resource resource = 1;\n\n  // A list of ScopeLogs that originate from a resource.\n  repeated ScopeLogs scope_logs = 2;\n\n  // The Schema URL, if known. This is the identifier of the Schema that the resource data\n  // is recorded in. Notably, the last part of the URL path is the version number of the\n  // schema: http[s]://server[:port]/path/<version>. To learn more about Schema URL see\n  // https://opentelemetry.io/docs/specs/otel/schemas/#schema-url\n  // This schema_url applies to the data in the \"resource\" field. It does not apply\n  // to the data in the \"scope_logs\" field which have their own schema_url field.\n  string schema_url = 3;\n}\n\n// A collection of Logs produced by a Scope.\nmessage ScopeLogs {\n  // The instrumentation scope information for the logs in this message.\n  // Semantically when InstrumentationScope isn't set, it is equivalent with\n  // an empty instrumentation scope name (unknown).\n  opentelemetry.proto.common.v1.InstrumentationScope scope = 1;\n\n  // A list of log records.\n  repeated LogRecord log_records = 2;\n\n  // The Schema URL, if known. This is the identifier of the Schema that the log data\n  // is recorded in. Notably, the last part of the URL path is the version number of the\n  // schema: http[s]://server[:port]/path/<version>. To learn more about Schema URL see\n  // https://opentelemetry.io/docs/specs/otel/schemas/#schema-url\n  // This schema_url applies to the data in the \"scope\" field and all logs in the\n  // \"log_records\" field.\n  string schema_url = 3;\n}\n\n// Possible values for LogRecord.SeverityNumber.\nenum SeverityNumber {\n  // UNSPECIFIED is the default SeverityNumber, it MUST NOT be used.\n  SEVERITY_NUMBER_UNSPECIFIED = 0;\n  SEVERITY_NUMBER_TRACE  = 1;\n  SEVERITY_NUMBER_TRACE2 = 2;\n  SEVERITY_NUMBER_TRACE3 = 3;\n  SEVERITY_NUMBER_TRACE4 = 4;\n  SEVERITY_NUMBER_DEBUG  = 5;\n  SEVERITY_NUMBER_DEBUG2 = 6;\n  SEVERITY_NUMBER_DEBUG3 = 7;\n  SEVERITY_NUMBER_DEBUG4 = 8;\n  SEVERITY_NUMBER_INFO   = 9;\n  SEVERITY_NUMBER_INFO2  = 10;\n  SEVERITY_NUMBER_INFO3  = 11;\n  SEVERITY_NUMBER_INFO4  = 12;\n  SEVERITY_NUMBER_WARN   = 13;\n  SEVERITY_NUMBER_WARN2  = 14;\n  SEVERITY_NUMBER_WARN3  = 15;\n  SEVERITY_NUMBER_WARN4  = 16;\n  SEVERITY_NUMBER_ERROR  = 17;\n  SEVERITY_NUMBER_ERROR2 = 18;\n  SEVERITY_NUMBER_ERROR3 = 19;\n  SEVERITY_NUMBER_ERROR4 = 20;\n  SEVERITY_NUMBER_FATAL  = 21;\n  SEVERITY_NUMBER_FATAL2 = 22;\n  SEVERITY_NUMBER_FATAL3 = 23;\n  SEVERITY_NUMBER_FATAL4 = 24;\n}\n\n// LogRecordFlags represents constants used to interpret the\n// LogRecord.flags field, which is protobuf 'fixed32' type and is to\n// be used as bit-fields. Each non-zero value defined in this enum is\n// a bit-mask.  To extract the bit-field, for example, use an\n// expression like:\n//\n//   (logRecord.flags & LOG_RECORD_FLAGS_TRACE_FLAGS_MASK)\n//\nenum LogRecordFlags {\n  // The zero value for the enum. Should not be used for comparisons.\n  // Instead use bitwise \"and\" with the appropriate mask as shown above.\n  LOG_RECORD_FLAGS_DO_NOT_USE = 0;\n\n  // Bits 0-7 are used for trace flags.\n  LOG_RECORD_FLAGS_TRACE_FLAGS_MASK = 0x000000FF;\n\n  // Bits 8-31 are reserved for future use.\n}\n\n// A log record according to OpenTelemetry Log Data Model:\n// https://github.com/open-telemetry/oteps/blob/main/text/logs/0097-log-data-model.md\nmessage LogRecord {\n  reserved 4;\n\n  // time_unix_nano is the time when the event occurred.\n  // Value is UNIX Epoch time in nanoseconds since 00:00:00 UTC on 1 January 1970.\n  // Value of 0 indicates unknown or missing timestamp.\n  fixed64 time_unix_nano = 1;\n\n  // Time when the event was observed by the collection system.\n  // For events that originate in OpenTelemetry (e.g. using OpenTelemetry Logging SDK)\n  // this timestamp is typically set at the generation time and is equal to Timestamp.\n  // For events originating externally and collected by OpenTelemetry (e.g. using\n  // Collector) this is the time when OpenTelemetry's code observed the event measured\n  // by the clock of the OpenTelemetry code. This field MUST be set once the event is\n  // observed by OpenTelemetry.\n  //\n  // For converting OpenTelemetry log data to formats that support only one timestamp or\n  // when receiving OpenTelemetry log data by recipients that support only one timestamp\n  // internally the following logic is recommended:\n  //   - Use time_unix_nano if it is present, otherwise use observed_time_unix_nano.\n  //\n  // Value is UNIX Epoch time in nanoseconds since 00:00:00 UTC on 1 January 1970.\n  // Value of 0 indicates unknown or missing timestamp.\n  fixed64 observed_time_unix_nano = 11;\n\n  // Numerical value of the severity, normalized to values described in Log Data Model.\n  // [Optional].\n  SeverityNumber severity_number = 2;\n\n  // The severity text (also known as log level). The original string representation as\n  // it is known at the source. [Optional].\n  string severity_text = 3;\n\n  // A value containing the body of the log record. Can be for example a human-readable\n  // string message (including multi-line) describing the event in a free form or it can\n  // be a structured data composed of arrays and maps of other values. [Optional].\n  opentelemetry.proto.common.v1.AnyValue body = 5;\n\n  // Additional attributes that describe the specific event occurrence. [Optional].\n  // Attribute keys MUST be unique (it is not allowed to have more than one\n  // attribute with the same key).\n  // The behavior of software that receives duplicated keys can be unpredictable.\n  repeated opentelemetry.proto.common.v1.KeyValue attributes = 6;\n  uint32 dropped_attributes_count = 7;\n\n  // Flags, a bit field. 8 least significant bits are the trace flags as\n  // defined in W3C Trace Context specification. 24 most significant bits are reserved\n  // and must be set to 0. Readers must not assume that 24 most significant bits\n  // will be zero and must correctly mask the bits when reading 8-bit trace flag (use\n  // flags & LOG_RECORD_FLAGS_TRACE_FLAGS_MASK). [Optional].\n  fixed32 flags = 8;\n\n  // A unique identifier for a trace. All logs from the same trace share\n  // the same `trace_id`. The ID is a 16-byte array. An ID with all zeroes OR\n  // of length other than 16 bytes is considered invalid (empty string in OTLP/JSON\n  // is zero-length and thus is also invalid).\n  //\n  // This field is optional.\n  //\n  // The receivers SHOULD assume that the log record is not associated with a\n  // trace if any of the following is true:\n  //   - the field is not present,\n  //   - the field contains an invalid value.\n  bytes trace_id = 9;\n\n  // A unique identifier for a span within a trace, assigned when the span\n  // is created. The ID is an 8-byte array. An ID with all zeroes OR of length\n  // other than 8 bytes is considered invalid (empty string in OTLP/JSON\n  // is zero-length and thus is also invalid).\n  //\n  // This field is optional. If the sender specifies a valid span_id then it SHOULD also\n  // specify a valid trace_id.\n  //\n  // The receivers SHOULD assume that the log record is not associated with a\n  // span if any of the following is true:\n  //   - the field is not present,\n  //   - the field contains an invalid value.\n  bytes span_id = 10;\n\n  // A unique identifier of event category/type.\n  // All events with the same event_name are expected to conform to the same\n  // schema for both their attributes and their body.\n  //\n  // Recommended to be fully qualified and short (no longer than 256 characters).\n  //\n  // Presence of event_name on the log record identifies this record\n  // as an event.\n  //\n  // [Optional].\n  string event_name = 12;\n}\n";

